class ConexionBD:
    def __init__(self, url: str):
        self.url = url
        self.conexion = None

    def __enter__(self):
        print(f"Conectando a {self.url}")
        self.conexion = {"url": self.url, "activa": True}
        return self.conexion

    def __exit__(self, *args):
        if self.conexion:
            self.conexion["activa"] = False
            print("Conexión cerrada")
        return False

with ConexionBD("sqlite:///app.db") as conn:
    print(f"Conexión activa: {conn['activa']}")

from contextlib import contextmanager

@contextmanager
def transaccion(db):
    """Simula una transacción de base de datos."""
    try:
        yield db
        db.commit()
        print("Commit exitoso")
    except Exception as e:
        db.rollback()
        print(f"Rollback por: {e}")
        raise

